const lawyerMap = {
  'H1B': 'namrata@s3ktech.ai',
  'L1':  'visputenamrata3@outlook.com',
  'OPT': 'namrata.vispute@vit.edu.in',
  'O1':  'lawyer.o1@lawfirm.com',
  'TN':  'lawyer.tn@lawfirm.com'
};

const d = $input.item.json;
const vt = (d['Visa_Type'] || 'H1B').toString().trim();
const existing = (d['Assigned_Lawyer_Email'] || '').toString().trim();
const assigned = existing || lawyerMap[vt] || 'namrata@s3ktech.ai';

return {
  json: {
    Case_ID:               (d['Case_ID']               || '').toString().trim(),
    Employee_Name:         (d['Employee_Name']         || '').toString().trim(),
    Employee_Email:        (d['Employee_Email']        || '').toString().trim(),
    Manager_Email:         (d['Manager_Email']         || '').toString().trim(),
    HR_Email:              (d['HR_Email']               || '').toString().trim(),
    Assigned_Lawyer_Email: assigned,
    Visa_Type:             vt,
    Priority:              (d['Priority']               || 'Normal').toString().trim(),
    Filing_Deadline:       (d['Filing_Deadline']       || '').toString().trim(),
    Documents_Submitted:   (d['Documents_Submitted']   || 'No').toString().trim().toLowerCase(),
    Docs_Complete:         (d['Docs_Complete']         || 'No').toString().trim().toLowerCase(),
    USCIS_Decision:        (d['USCIS_Decision']        || 'Pending').toString().trim(),
    RFE_Due_Date:          (d['RFE_Due_Date']          || '').toString().trim(),
    Reminder_Count:        parseInt(d['Reminder_Count'] || '0'),
    Rework_Count:          parseInt(d['Rework_Count']   || '0'),
    Status:                (d['Status']                 || '').toString().trim()
  }
};

